const { app, BrowserWindow } = require('electron');
const { writeFileSync } = require('node:fs');
const { join } = require('node:path');
app.setName('PI Review Feedback Test');
app.whenReady().then(async () => {
  const win = new BrowserWindow({ show: false, width: 1100, height: 850, useContentSize: true,
    webPreferences: { sandbox: true, contextIsolation: true, backgroundThrottling: false } });
  const errors = [];
  win.webContents.on('console-message', (_event, level, message) => { if (level >= 3) errors.push(message); });
  await win.loadURL(process.env.PI_REVIEW_FIXTURE_URL);
  const run = (code) => win.webContents.executeJavaScript(code);
  const wait = (condition) => run(`new Promise((resolve,reject)=>{const end=Date.now()+10000;function check(){if(${condition})return resolve();if(Date.now()>end)return reject(new Error('Condition timed out: '+${JSON.stringify(condition)}));requestAnimationFrame(check)}check()})`);
  await wait('window.reviewFixture');
  const results = [];
  const check = async (name, condition) => { await wait(condition); results.push({ name, ok: true }); console.log('PASS ' + name); };
  async function click(selector, modifiers = []) {
    const point = await run(`(()=>{const e=document.querySelector(${JSON.stringify(selector)});if(!e)throw new Error('Missing '+${JSON.stringify(selector)});e.scrollIntoView({block:'nearest'});const r=e.getBoundingClientRect();return {x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)}})()`);
    win.webContents.sendInputEvent({ type:'mouseDown', button:'left', clickCount:1, modifiers, ...point });
    win.webContents.sendInputEvent({ type:'mouseUp', button:'left', clickCount:1, modifiers, ...point });
    await run('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');
  }
  const capture = async (name) => writeFileSync(join(process.env.PI_REVIEW_ARTIFACT_DIR, name + '.png'), (await win.webContents.capturePage()).toPNG());
  const frame = () => run('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');
  const point = (selector) => run(`(()=>{const e=document.querySelector(${JSON.stringify(selector)});const r=e.getBoundingClientRect();return {x:Math.round(r.x+9),y:Math.round(r.y+r.height/2)}})()`);
  const firstPlus = '.review-tab [data-review-hunk="0"][data-review-line="0"] .review-line-select';
  const thirdPlus = '.review-tab [data-review-hunk="0"][data-review-line="2"] .review-line-select';
  async function drag(from, to, cancel = false) {
    const start=await point(from);
    win.webContents.sendInputEvent({type:'mouseMove',...start});
    win.webContents.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,...start});
    await frame();
    const end=await point(to);
    win.webContents.sendInputEvent({type:'mouseMove',...end});
    await frame();
    await check('drag highlights code before showing the editor', 'document.querySelectorAll(".review-tab .is-feedback-selected").length === 3 && !document.querySelector(".review-feedback-form")');
    if(cancel) await run('window.dispatchEvent(new Event("blur"))');
    win.webContents.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,...end});
    await frame();
  }
  const stage = async () => {
    const sendsBefore = await run('window.reviewFixture.requests.length + window.reviewFixture.queued.length');
    if (!(await run('!!document.querySelector(".review-line-select")'))) await click('.review-tab .review-change-card-header');
    await drag(firstPlus, thirdPlus);
    await check('comment editor follows the selected line', '(()=>{const p=document.querySelector(".review-feedback-form").previousElementSibling;return (p.matches(".review-pending-feedback") ? p.previousElementSibling : p).classList.contains("is-feedback-selected")})()');
    await click('.review-feedback-form textarea');
    win.webContents.insertText('Preserve the original error recovery.');
    await wait('document.querySelector(".review-feedback-form textarea").value.length > 0');
    await click('.review-feedback-form button');
    await check('selection stages an attachment without sending', '!!document.querySelector(".review-pending-feedback") && window.reviewFixture.requests.length + window.reviewFixture.queued.length === ' + sendsBefore);
  };
  if (process.env.PI_REVIEW_BASELINE === '1') { await click('.review-tab .review-change-card-header'); await capture('before'); win.destroy(); app.exit(0); return; }
  await check('collapsed transcript change has no review or open actions', '!document.querySelector("[data-review-transcript] .review-navigate")');
  await click('[data-review-transcript] .review-change-card-header');
  await check('actions occupy the expanded diff bottom right', '(()=>{const a=document.querySelector("[data-review-transcript] .review-change-card-body .review-open-file");const b=document.querySelector("[data-review-transcript] .review-change-card-body");return !!a && a.getBoundingClientRect().right <= b.getBoundingClientRect().right && a.closest(".review-change-card-actions").getBoundingClientRect().right >= b.getBoundingClientRect().right-20 && a.getBoundingClientRect().top >= [...b.querySelectorAll(".diff-line")].at(-1).getBoundingClientRect().bottom})()');
  await click('[data-review-transcript] .review-change-card-header');
  await check('collapsing removes the actions', '!document.querySelector("[data-review-transcript] .review-navigate")');
  await click('[data-review-transcript] .review-change-card-header');
  await click('[data-review-transcript] .review-open-file');
  await check('Open uses the existing resolved file preview route', 'window.reviewFixture.state().fileRequest?.path === "src/recover.ts"');
  await click('[data-review-transcript] .review-navigate');
  await check('Review opens and expands the owning recorded change', 'document.querySelector(".review-tab .review-change-card-header").getAttribute("aria-expanded") === "true"');
  await check('transcript diff stays read-only', '!document.querySelector("[data-review-transcript] .review-line-select") && !!document.querySelector("[data-review-transcript] .diff-line")');
  await check('Review Open and rollback share the expanded action row', '(()=>{const row=document.querySelector("[data-review-transcript] .review-change-card-actions");const a=row.querySelector(".review-navigate").getBoundingClientRect();const b=[...row.querySelectorAll("button")].at(-1).getBoundingClientRect();return Math.abs(a.y-b.y)<2})()');
  await check('all three action gaps are identical', '(()=>{const b=[...document.querySelectorAll("[data-review-transcript] .review-change-card-actions button")];const r=b.map(e=>e.getBoundingClientRect());return b.length===3 && b.every(e=>e.parentElement===b[0].parentElement) && Math.abs((r[1].left-r[0].right)-(r[2].left-r[1].right))<1})()');
  await check('no permanent selection instructions', '!document.querySelector(".review-feedback-editor > .review-change-note")');
  await click(firstPlus);
  await check('click plus opens and focuses a single-line comment', 'document.querySelectorAll(".review-tab .is-feedback-selected").length === 1 && document.activeElement === document.querySelector(".review-feedback-form textarea")');
  await click(thirdPlus, ['shift']);
  await check('Shift remains an optional range shortcut', 'document.querySelectorAll(".review-tab .is-feedback-selected").length === 3');
  await click('.review-feedback-form button:last-child');
  await drag(thirdPlus, firstPlus);
  await check('upward drag opens the comment after release', '!!document.querySelector(".review-feedback-form") && document.activeElement === document.querySelector(".review-feedback-form textarea")');
  await click('.review-feedback-form button:last-child');
  await drag(firstPlus, thirdPlus, true);
  await check('losing window focus cancels a drag without staging a comment', '!document.querySelector(".review-feedback-form,.review-pending-feedback") && document.querySelectorAll(".review-tab .is-feedback-selected").length === 0');

  await stage();
  await check('feedback belongs to Review, never above the composer', '!!document.querySelector(".review-tab .review-pending-feedback") && !document.querySelector(".composer-review-feedback")');
  await stage();
  await check('a second comment cannot replace an unsent one', 'document.querySelector(".review-feedback-form [role=alert]").textContent.includes("pending comment")');
  await click('.review-feedback-form button:last-child');
  await check('saved comment is embedded after its last selected line', 'document.querySelector(".review-pending-feedback").previousElementSibling.matches(".diff-line.add") && document.querySelector(".review-pending-feedback").parentElement.classList.contains("diff-hunk")');
  await click('.review-tab .review-change-card-header');
  await check('collapsed diff shows a comment marker instead of a floating card', '!!document.querySelector(".review-tab .review-comment-marker") && !document.querySelector(".review-pending-feedback")');
  await click('.review-tab .review-change-card-header');
  await capture('after');
  await run('window.reviewFixture.switchSession("b")');
  await check('session switch hides attachment', '!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.switchSession("a","/other")');
  await check('workspace switch hides attachment', '!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.switchSession("a")');
  await check('return restores the owning attachment', '!!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.remount()');
  await check('remount retains pending comment', '!!document.querySelector(".review-pending-feedback")');
  await click('.send-btn');
  await check('real send store delivers historical context to IPC', 'window.reviewFixture.requests.length === 1 && window.reviewFixture.requests[0].sessionId === "a" && window.reviewFixture.requests[0].content.includes("historical evidence, not current file coordinates") && window.reviewFixture.requests[0].content.includes("Preserve the original error recovery.")');
  await check('accepted send clears attachment', '!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.running(false); window.reviewFixture.reject=true');
  await stage();
  await click('.send-btn');
  await check('rejected send restores attachment', 'window.reviewFixture.requests.length === 2 && !!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.defer=true');
  await click('.send-btn');
  await wait('window.reviewFixture.requests.length === 3');
  await run('window.reviewFixture.switchSession("b"); window.reviewFixture.release()');
  await check('late rejection cannot attach to another session', '!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.switchSession("a"); window.reviewFixture.defer=false');
  await check('late rejection restores only its source draft', '!!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.reject=false; window.reviewFixture.running(true)');
  await click('.send-btn');
  await check('running turn queues feedback', 'window.reviewFixture.queued.length === 1 && window.reviewFixture.queued[0].content.includes("snapshot-a") && !document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.editQueue()');
  await check('editing queue restores structured attachment', '!!document.querySelector(".review-pending-feedback")');
  await click('.review-pending-feedback button');
  await check('remove affects only the pending comment', '!document.querySelector(".review-pending-feedback")');
  await run('window.reviewFixture.running(false)');
  await stage();
  await click('.review-tab .review-change-card-actions .review-change-rollback');
  await check('rollback retains conflict guard', 'document.body.textContent.includes("rollback was skipped")');
  await run('window.reviewFixture.locale("zh-CN","light")');
  win.setContentSize(520,850);
  await check('localized attachment stays available', 'document.querySelector(".review-pending-feedback").textContent.includes("待发送")');
  await capture('after-zh-narrow');
  await check('narrow layout has no horizontal page overflow', 'document.documentElement.scrollWidth <= innerWidth');
  await click('.review-pending-feedback button');
  await run('window.reviewFixture.longChange()');
  await click('.review-tab .review-change-card-header');
  await run('document.querySelector(".review-tab .review-change-card-body").scrollTop=0; document.querySelector(".review-tab .review-line-select").addEventListener("pointerdown",e=>window.reviewFixture.activePointer=e.pointerId,{once:true})');
  const scrollStart = await point(firstPlus);
  win.webContents.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,...scrollStart});
  await frame();
  const edge=await run('(()=>{const r=document.querySelector(".review-tab .review-change-card-body").getBoundingClientRect();return {x:Math.round(r.x+20),y:Math.round(Math.min(innerHeight-8,r.bottom-3))}})()');
  win.webContents.sendInputEvent({type:'mouseMove',...edge});
  await check('dragging near the diff edge scrolls and extends the selection', 'document.querySelector(".review-tab .review-change-card-body").scrollTop >= 20 && document.querySelectorAll(".review-tab .is-feedback-selected").length > 3');
  await run('document.querySelector(".review-tab .review-line-select").dispatchEvent(new PointerEvent("pointercancel",{pointerId:window.reviewFixture.activePointer,bubbles:true}))');
  win.webContents.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,...edge});
  await check('pointer cancellation releases the tentative range', '!document.querySelector(".review-feedback-form") && document.querySelectorAll(".review-tab .is-feedback-selected").length === 0');
  const stoppedScroll=await run('document.querySelector(".review-tab .review-change-card-body").scrollTop');
  await frame();
  await check('cancelled drag stops the scroll loop', 'document.querySelector(".review-tab .review-change-card-body").scrollTop === '+stoppedScroll);
  await run('document.querySelector(".review-tab .review-change-card-body").scrollTop=0');
  win.webContents.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,...await point(firstPlus)});
  await frame();
  await run('window.reviewFixture.switchSession("b")');
  win.webContents.sendInputEvent({type:'mouseMove',...edge});
  win.webContents.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,...edge});
  await check('session switch during capture cannot open a comment elsewhere', '!document.querySelector(".review-feedback-form,.review-pending-feedback")');
  if (errors.length) throw new Error('Renderer errors: ' + errors.join('\n'));
  writeFileSync(join(process.env.PI_REVIEW_ARTIFACT_DIR,'results.json'),JSON.stringify(results,null,2));
  console.log('SUMMARY ' + results.length + ' passed');
  win.destroy(); app.exit(0);
}).catch(error=>{ console.error(error.stack); app.exit(1); });
